import { DEFAULT_MEDIA_CACHE_CONTROL } from './getDownloadResponseHeaderPolicy.js';
export const resolveDownloadResponseHeaders = ({ collection, payloadResponseHeaders })=>{
    let headers = new Headers(payloadResponseHeaders);
    if (!headers.has('Cache-Control')) {
        headers.set('Cache-Control', DEFAULT_MEDIA_CACHE_CONTROL);
    }
    if (collection.upload && typeof collection.upload === 'object' && typeof collection.upload.modifyResponseHeaders === 'function') {
        headers = collection.upload.modifyResponseHeaders({
            headers
        }) || headers;
    }
    return headers;
};
